import test from 'node:test';
import assert from 'node:assert/strict';
import {validateGateCatalog, buildCodonCatalog, persistenceState, SynthiaModelRouter, DEFAULT_PROVIDER_CATALOG, McpToolBroker, SynthiaBuildPipeline} from '../src/index.mjs';

function gates(){ return Array.from({length:64},(_,i)=>({gate:i+1,name:`Gate ${i+1}`,center:'G',keyword:`K${i+1}`,circuit:'Test',channel_name:`${i+1}-${((i+7)%64)+1}`,harmonic:((i+7)%64)+1,biology:'Test biology',amino:'Met',binary_code:(i%64).toString(2).padStart(6,'0'),dimension_affinity:['Movement','Evolution','Being','Design','Space'][i%5],pressure:'Mind',states:{distortion:`D${i+1}`,resonance:`R${i+1}`,convergence:`C${i+1}`}})); }

test('canonical gate validator requires complete unique 1..64 catalog',()=>{ const rows=gates(); assert.equal(validateGateCatalog(rows).ok,true); assert.equal(buildCodonCatalog(rows).length,64); rows[62].gate=64; const bad=validateGateCatalog(rows); assert.equal(bad.ok,false); assert.match(bad.errors.join('|'),/duplicate gate: 64|missing gate: 63/); });
test('neutral stays UI-only and cannot silently mutate canonical substrate',()=>{ assert.equal(persistenceState('neutral'),null); assert.equal(persistenceState('resonance'),'resonance'); });
test('provider voice keeps Synthia ownership/provenance',async()=>{ const r=new SynthiaModelRouter({synthia:{respond:async()=> 'local'},transport:{invoke:async(p)=>`external:${p.id}`}}); DEFAULT_PROVIDER_CATALOG.slice(1).forEach(p=>r.registerProvider(p)); r.select({providerId:'anthropic',mode:'provider_voice'}); const out=await r.respond('hi'); assert.equal(out.result,'external:anthropic'); assert.equal(out.systemOwner,'synthia'); assert.equal(out.toolAuthority,'synthia'); assert.equal(out.delegated,true); });
test('delegate mode returns through Synthia',async()=>{ let ctx; const r=new SynthiaModelRouter({synthia:{respond:async(_i,c)=>{ctx=c;return 'integrated';}},transport:{invoke:async()=> 'consult'}}); r.registerProvider({id:'openai',label:'GPT',external:true}); r.select({providerId:'openai',mode:'delegate'}); const out=await r.respond('x',{a:1}); assert.equal(out.result,'integrated'); assert.equal(ctx.externalConsult.output,'consult'); });
test('MCP broker is authority boundary and logs calls',async()=>{ const logs=[]; const b=new McpToolBroker({authorize:async({provider})=>provider!=='blocked',ledger:async x=>logs.push(x)}); b.register({name:'sum',handler:({a,b})=>a+b}); assert.equal(await b.call({provider:'openai',name:'sum',input:{a:2,b:3}}),5); await assert.rejects(()=>b.call({provider:'blocked',name:'sum',input:{}}),/denied/); assert.equal(logs.length,1); });
test('self-build pipeline stages, verifies, and requires approval',async()=>{ const mem={}; const store={stage:async x=>mem.staged=x,update:async x=>mem.updated=x,snapshotLive:async()=>({v:1}),apply:async x=>mem.live=x,restore:async x=>mem.restored=x}; const p=new SynthiaBuildPipeline({validator:async()=>({ok:true}),tester:async()=>({ok:true,passed:5,failed:0}),store}); const s=await p.stage({title:'x',files:{'a.js':'export default 1'}}); const v=await p.verify(s); assert.equal(v.status,'verified'); await assert.rejects(()=>p.apply(v),/approval/); const a=await p.apply(v,{approved:true}); assert.equal(a.status,'applied'); assert.equal(mem.live.id,s.id); });

test('OpenAI Responses transport uses bearer auth and preserves Synthia ownership instruction',async()=>{ let req; const {HttpProviderTransport}=await import('../src/http-provider-transport.mjs'); const t=new HttpProviderTransport({credentialResolver:async()=> 'k',fetchImpl:async(url,init)=>{req={url,init};return {ok:true,status:200,json:async()=>({id:'r1',output_text:'ok'})}}}); const out=await t.invoke({id:'openai',model:'model-x'},{input:'hello'}); assert.equal(out.text,'ok'); assert.match(req.url,/api\.openai\.com\/v1\/responses/); assert.equal(req.init.headers.authorization,'Bearer k'); assert.match(req.init.body,/Synthia retains system context/); });
test('Anthropic transport uses Messages API headers and parses text blocks',async()=>{ let req; const {HttpProviderTransport}=await import('../src/http-provider-transport.mjs'); const t=new HttpProviderTransport({credentialResolver:async()=> 'a',fetchImpl:async(url,init)=>{req={url,init};return {ok:true,status:200,json:async()=>({id:'m1',content:[{type:'text',text:'claude'}]})}}}); const out=await t.invoke({id:'anthropic',model:'claude-current'},{input:'hello'}); assert.equal(out.text,'claude'); assert.match(req.url,/api\.anthropic\.com\/v1\/messages/); assert.equal(req.init.headers['x-api-key'],'a'); assert.equal(req.init.headers['anthropic-version'],'2023-06-01'); });
test('xAI transport uses Responses-compatible endpoint',async()=>{ let req; const {HttpProviderTransport}=await import('../src/http-provider-transport.mjs'); const t=new HttpProviderTransport({credentialResolver:async()=> 'x',fetchImpl:async(url,init)=>{req={url,init};return {ok:true,status:200,json:async()=>({id:'x1',output:[{content:[{text:'grok'}]}]})}}}); const out=await t.invoke({id:'xai',model:'grok-current'},{input:'hello'}); assert.equal(out.text,'grok'); assert.match(req.url,/api\.x\.ai\/v1\/responses/); assert.equal(req.init.headers.authorization,'Bearer x'); });
